// Generate or check the API types from the committed OpenAPI snapshot. No network access.
//
//   npm run api:types         # rewrite src/api/schema.d.ts from ../api/openapi.json
//   npm run api:types:check   # exit 1 if src/api/schema.d.ts is out of date
import { readFileSync, writeFileSync } from 'node:fs'
import { relative, resolve } from 'node:path'
import { parseArgs } from 'node:util'
import openapiTS, { astToString } from 'openapi-typescript'

const WEBSITE = resolve(import.meta.dirname, '..')
const HEADER =
  '/* Generated by `npm run api:types` from api/openapi.json. Do not edit by hand. */\n\n'

const { values } = parseArgs({
  options: {
    check: { type: 'boolean', default: false },
    input: { type: 'string', default: resolve(WEBSITE, '..', 'api', 'openapi.json') },
    output: { type: 'string', default: resolve(WEBSITE, 'src', 'api', 'schema.d.ts') },
  },
})

const schema = JSON.parse(readFileSync(values.input, 'utf8'))
const expected = HEADER + astToString(await openapiTS(schema))
const name = relative(WEBSITE, values.output)

if (values.check) {
  let current = ''
  try {
    current = readFileSync(values.output, 'utf8')
  } catch {
    // A missing file is out of date too.
  }
  if (current !== expected) {
    console.error(`${name} is out of date: run \`npm run api:types\``)
    process.exit(1)
  }
} else {
  writeFileSync(values.output, expected)
}
